    }

    // Also check reversed: 0 == length(x)
    if right.kind() == "function_call" {
        if let Some(name) = extract_func_name(right, source) {
            if name == "length" || name == "numel" {
                return Some((name, node_text(left, source).trim()));
            }
        }
    }

    None
}

