/// Checks dispatched for `matrix` nodes.
fn check_matrix(
    &self,
    ctx: &NodeContext,
    results: &mut Vec<Diagnostic>,
) {
    let node = ctx.node;
    let source = ctx.source;

    // NBRAK2: unnecessary brackets [x] for scalar
    self.check_unnecessary_brackets(node, source, results);
}

